functions.nand:
static _Bool nand(_Bool a, _Bool b)
{
    return !(a && b);
}

functions.or:
static _Bool or (_Bool a, _Bool b)
{
    return nand(not(a), not(b));
}

functions.and:
static _Bool and (_Bool a, _Bool b)
{
    return not(nand(a, b));
}

functions.add_bit:
static _Bool
    add_bit(_Bool a, _Bool b, _Bool carry, _Bool *carry_result)
{
    *carry_result = and(or (a, b), or (and(a, b), carry));
    return xor(xor(a, b), carry);
}

functions.half_sub:
static _Bool half_sub(_Bool a, _Bool b, _Bool *carry_result)
{
    *carry_result = and(not(a), b);
    return xor(a, b);
}

functions.sub_bit:
static _Bool sub_bit(_Bool a, _Bool b, _Bool carry, _Bool *carry_result)
{
    _Bool b1;
    _Bool b2;
    _Bool result = half_sub(half_sub(a, b, &b1), carry, &b2);
    *carry_result = or (b1, b2);
    return result;
}

functions.print_add_bit:
void print_add_bit(_Bool a, _Bool b, _Bool carry)
{
    printf("a      : %s\n", bll(a));
    printf("b      : %s\n", bll(b));
    printf("carry  : %s\n", bll(carry));
    _Bool res_carry;
    printf("result :\n");
    printf("  bit  : %s\n", bll(add_bit(a, b, carry, &res_carry)));
    printf("  carry: %s\n", bll(res_carry));
}

functions.add_u4:
u4 add_u4(u4 a, u4 b)
{
    _Bool carry = 0;
    u4 result = 0;
    result |= ((u4)add_bit((a >> 0) & 0b1, (b >> 0) & 0b1, carry, &carry)) << 0;
    result |= ((u4)add_bit((a >> 1) & 0b1, (b >> 1) & 0b1, carry, &carry)) << 1;
    result |= ((u4)add_bit((a >> 2) & 0b1, (b >> 2) & 0b1, carry, &carry)) << 2;
    result |= ((u4)add_bit((a >> 3) & 0b1, (b >> 3) & 0b1, carry, &carry)) << 3;
    return result;
}

functions.sub_u4:
u4 sub_u4(u4 a, u4 b)
{
    _Bool carry = 0;
    u4 result = 0;
    result |= ((u4)sub_bit((a >> 0) & 0b1, (b >> 0) & 0b1, carry, &carry)) << 0;
    result |= ((u4)sub_bit((a >> 1) & 0b1, (b >> 1) & 0b1, carry, &carry)) << 1;
    result |= ((u4)sub_bit((a >> 2) & 0b1, (b >> 2) & 0b1, carry, &carry)) << 2;
    result |= ((u4)sub_bit((a >> 3) & 0b1, (b >> 3) & 0b1, carry, &carry)) << 3;
    return result;
}
